package at.andrew.squashtap;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowDialog;import org.robolectric.util.ReflectionHelpers;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,application=Application.class,qualifiers="w192dp-h192dp-round") @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.LEGACY)
public class KeepScoreFeaturesUiTest {
 private ActivityController<MainActivity> controller;private MainActivity a;private SharedPreferences p;
 @Before public void setup(){p=RuntimeEnvironment.getApplication().getSharedPreferences("squash",0);MatchBook b=new MatchBook(new MatchState("current",3));b.add(0);p.edit().clear().putString("match_book",b.encode()).putString("opponent_book",new OpponentDirectory().encode()).putString(MatchDisplayPolicy.ACTIVE_MATCH,"current").putBoolean("asked_match_notification",true).commit();controller=Robolectric.buildActivity(MainActivity.class).setup();a=controller.get();a.action(TouchTargets.MENU);}
 @After public void stop(){Dialog d=ShadowDialog.getLatestDialog();if(d!=null)d.dismiss();controller.pause().stop().destroy();}
 private List<View> views(View root){List<View> out=new ArrayList<>();out.add(root);if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++)out.addAll(views(((ViewGroup)root).getChildAt(i)));return out;}
 private List<View> views(){return views(ShadowDialog.getLatestDialog().getWindow().getDecorView());}
 private Button button(String label){for(View v:views())if(v instanceof Button&&((Button)v).getText().toString().split("\n")[0].equals(label))return (Button)v;throw new AssertionError("Missing "+label);}
 private void click(String label){button(label).performClick();}
 private MatchBook book(){return MatchBook.decode(p.getString("match_book",""));}
 private EditText input(){for(View v:views())if(v instanceof EditText)return (EditText)v;throw new AssertionError("Missing input");}
 private void pickle(){click("Current match");click("Cancel match");click("Discard match");click("Change sport");click("Pickleball");click("New Pickleball match");}
 @Test public void ownNameIsOptionalAndDoesNotCreateAnOpponent(){String before=p.getString("opponent_book","");click("Players");click("Your name: Me");input().setText("André");click("Save your name");assertEquals("André",p.getString("my_name",""));assertEquals(before,p.getString("opponent_book",""));ScoreView score=ReflectionHelpers.getField(a,"counter");assertTrue(score.getContentDescription().toString().contains("André"));click("Your name: André");input().setText("");click("Save your name");assertEquals("",p.getString("my_name",""));}
 @Test public void pickleballDefaultAndRuleChoicePersistWithServeAwareUndo(){pickle();click("Scoring: Traditional side-out");click("Rally 2025 · win on serve");click("Match length: Best of 3");click("Best of 1 · first to 1");click("Create match");assertEquals("rally-2025",book().current().format().deuce);assertEquals(1,book().current().bestOf());assertEquals(0,book().current().server());a.action(TouchTargets.RED);assertEquals(1,book().current().game().red());a.action(TouchTargets.UNDO);assertEquals(0,book().current().game().red());assertEquals(0,book().current().server());}
 @Test public void traditionalReceivingWinChangesServerWithoutPoint(){pickle();click("Create match");a.action(TouchTargets.RED);assertEquals(0,book().current().game().red());assertEquals(1,book().current().server());assertEquals(1,book().current().game().rallies());}
 @Test public void favouriteFormatDoesNotCreateOrReplaceTheCurrentMatch(){click("Current match");click("Match options");click("New match");String before=book().encode();click("Save as favourite");input().setText("Weekly squash");click("Save favourite");assertEquals(before,book().encode());assertEquals(1,MatchPresets.decode(p.getString("favourite_formats","")).list("squash").size());click("Cancel");}
 @Test public void quickRematchKeepsHistoryPlayersAndRulesWithFreshIdentity(){MatchBook b=ReflectionHelpers.getField(a,"book");OpponentDirectory d=ReflectionHelpers.getField(a,"opponents");String opponent=d.add("Pat");d.assign(b.current().id(),opponent);b.retire(1);ReflectionHelpers.callInstanceMethod(a,"afterMatchChange");ReflectionHelpers.callInstanceMethod(a,"showResult",ReflectionHelpers.ClassParameter.from(String.class,b.current().id()),ReflectionHelpers.ClassParameter.from(int.class,0));String id=b.current().id();click("Quick rematch");assertNotEquals(id,book().current().id());assertEquals(1,book().count());assertEquals("Pat",OpponentDirectory.decode(p.getString("opponent_book","")).nameFor(book().current().id()));assertEquals(0,book().currentStartedAt());assertFalse(book().current().hasPoints());}
 @Test public void openingBackupOrLiveOptionsDoesNotTransmitOrChangeScore(){String before=book().encode();click("Settings");click("Backup & restore");assertNotNull(button("Create or restore backup"));assertEquals(before,book().encode());click("Back to Settings");click("Back to Menu");click("Current match");click("Live scoreboard");assertNotNull(button("Start live sharing"));assertNull(LiveScoreClient.get(a).session());assertEquals(before,book().encode());}
 @Test public void widgetShortcutPreservesPauseAndNeverAwardsPoints(){p.edit().putBoolean("match_paused",true).remove(MatchDisplayPolicy.ACTIVE_MATCH).commit();String before=book().encode();Intent intent=new Intent(a,MainActivity.class).putExtra("keep_score_widget","match");controller.newIntent(intent);assertEquals(before,book().encode());assertTrue(p.getBoolean("match_paused",false));assertNotNull(button("Resume match"));}
 @Test public void widgetShowsNoAbandonedMatchAfterDiscard(){click("Current match");click("Cancel match");click("Discard match");assertFalse(MatchWidgets.read(a).present);}
 @Test public void menuHeadingUsesFullWidthAndShortcutDoesNotSqueezeIt(){click("Current match");TextView title=null;for(View v:views())if(v instanceof TextView&&!(v instanceof Button)&&((TextView)v).getText().toString().equals("Current match"))title=(TextView)v;assertNotNull(title);assertEquals(ViewGroup.LayoutParams.MATCH_PARENT,title.getLayoutParams().width);assertNotNull(button("Scoreboard"));assertTrue(button("Pause match").getMinimumHeight()>=48*a.getResources().getDisplayMetrics().density);}
 @Test public void backupRestorePreviewDoesNotAlterLocalStateBeforeConfirmation()throws Exception{String before=book().encode();MatchBook replacement=new MatchBook(new MatchState("restore-current",3));replacement.add(1);Map<String,String> settings=new HashMap<>();settings.put("my_name","Andrew");String backup=BackupArchive.create(replacement,new OpponentDirectory(),settings);TransferClient.Session session=new TransferClient.Session();session.expiresAt=System.currentTimeMillis()+600000;ReflectionHelpers.setField(a,"transferSnapshotBackup",true);org.json.JSONObject data=new org.json.JSONObject().put("restoreBackup",backup).put("baseDirectory",TransferClient.base(book(),ReflectionHelpers.getField(a,"opponents"))).put("currentMatchId",book().current().id());ReflectionHelpers.callInstanceMethod(a,"previewBackupRestore",ReflectionHelpers.ClassParameter.from(org.json.JSONObject.class,data),ReflectionHelpers.ClassParameter.from(TransferClient.Session.class,session));assertEquals(before,book().encode());click("Cancel");assertEquals(before,book().encode());}
 private org.json.JSONObject restorePayload(MatchBook replacement,Map<String,String> settings)throws Exception{ReflectionHelpers.setField(a,"transferSnapshotBackup",true);return new org.json.JSONObject().put("restoreBackup",BackupArchive.create(replacement,new OpponentDirectory(),settings)).put("baseDirectory",TransferClient.base(book(),ReflectionHelpers.getField(a,"opponents"))).put("currentMatchId",book().current().id());}
 private void restorePreview(org.json.JSONObject payload)throws Exception{TransferClient.Session session=new TransferClient.Session();session.expiresAt=System.currentTimeMillis()+600000;ReflectionHelpers.setField(a,"tasks",new LiveScoreClientUiTest.Queue());ReflectionHelpers.callInstanceMethod(a,"previewBackupRestore",ReflectionHelpers.ClassParameter.from(org.json.JSONObject.class,payload),ReflectionHelpers.ClassParameter.from(TransferClient.Session.class,session));}
 @Test public void confirmedRestoreIsAtomicPausedAndKeepsAnAccessibleRecoveryCopy()throws Exception{String old=book().encode();MatchBook replacement=new MatchBook(new MatchState("restored",3));replacement.add(1);Map<String,String> settings=new HashMap<>();settings.put("my_name","Andrew");settings.put("match_reminders","true");restorePreview(restorePayload(replacement,settings));click("Replace data & restore");assertEquals(replacement.encode(),book().encode());assertEquals("Andrew",p.getString("my_name",""));assertTrue(p.getBoolean("match_reminders",false));assertFalse(p.contains(MatchDisplayPolicy.ACTIVE_MATCH));assertTrue(p.getBoolean("match_paused",false));assertEquals(old,BackupArchive.parse(p.getString("backup_before_restore","")).book.encode());click("Back");assertNotNull(button("Download previous data copy"));}
 @Test public void changingWatchSettingsAfterRestorePreviewRejectsTheWholeReplace()throws Exception{String old=book().encode();MatchBook replacement=new MatchBook(new MatchState("restored",3));restorePreview(restorePayload(replacement,Collections.emptyMap()));p.edit().putString("my_name","Changed since preview").commit();click("Replace data & restore");assertEquals(old,book().encode());assertEquals("Changed since preview",p.getString("my_name",""));assertFalse(p.contains("backup_before_restore"));}
}
